select t.machine_id,t.machine_id machineId,t.log_id,t.log_id
logId,t.state,t.community_id,t.community_id communityId,t.user_name,t.user_name
userName,t.log_action,t.log_action logAction,t.user_id,t.user_id userId,
ac.machine_code machineCode,ac.machine_name machineName,td.name stateName
from access_control_log t
left join access_control ac on ac.machine_id = t.machine_id and ac.status_cd = '0'
left join t_dict td on t.state = td.status_cd and td.table_name = 'access_control_log' and td.table_columns = 'state'
where 1 =1

    and t.res_param= #{resParam}


    and t.machine_id= #{machineId}


    and t.log_id= #{logId}


    and t.req_param= #{reqParam}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.user_name= #{userName}


    and t.log_action= #{logAction}


    and t.user_id= #{userId}

order by t.create_time desc

    limit #{page}, #{row}

select t.log_id logId, t.res_param resParam,t.req_param reqParam
from access_control_log t
where 1 =1
and t.log_id= #{logId}
and t.community_id= #{communityId}

